let duration = endTime - startTime;
let stepSize = case(
        duration < 24h, 30s,        // Fine detail for short-term debugging
        duration < 3d,  5m,         // Slight aggregation
        duration < 7d,  15m,        // Up to ~7 days, still captures trends
        duration < 14d, 30m,        // Mid-range
